package main

import (
	"os"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("Permissions", func() {
	var originalEnv string

	BeforeEach(func() {
		originalEnv = os.Getenv("TODO_ADMIN_MODE")
		os.Unsetenv("TODO_ADMIN_MODE")
	})

	AfterEach(func() {
		if originalEnv != "" {
			os.Setenv("TODO_ADMIN_MODE", originalEnv)
		} else {
			os.Unsetenv("TODO_ADMIN_MODE")
		}
	})

	Context("isAdminMode", func() {
		It("should return true when TODO_ADMIN_MODE is set to true", func() {
			os.Setenv("TODO_ADMIN_MODE", "true")
			Expect(isAdminMode()).To(BeTrue())
		})

		It("should return true when TODO_ADMIN_MODE is set to TRUE", func() {
			os.Setenv("TODO_ADMIN_MODE", "TRUE")
			Expect(isAdminMode()).To(BeTrue())
		})

		It("should return true when TODO_ADMIN_MODE is set to True", func() {
			os.Setenv("TODO_ADMIN_MODE", "True")
			Expect(isAdminMode()).To(BeTrue())
		})

		It("should return false when TODO_ADMIN_MODE is not set", func() {
			Expect(isAdminMode()).To(BeFalse())
		})

		It("should return false when TODO_ADMIN_MODE is set to false", func() {
			os.Setenv("TODO_ADMIN_MODE", "false")
			Expect(isAdminMode()).To(BeFalse())
		})

		It("should return false when TODO_ADMIN_MODE is set to empty string", func() {
			os.Setenv("TODO_ADMIN_MODE", "")
			Expect(isAdminMode()).To(BeFalse())
		})
	})

})

package main

import (
	"os"
	"path/filepath"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("Storage", func() {
	var tempDir string
	var storage *FileStorage

	BeforeEach(func() {
		var err error
		tempDir, err = os.MkdirTemp("", "todo-test-*")
		Expect(err).NotTo(HaveOccurred())
		storage = NewFileStorage(filepath.Join(tempDir, "todos.json"))
	})

	AfterEach(func() {
		if tempDir != "" {
			os.RemoveAll(tempDir)
		}
	})

	Context("Storage interface", func() {
		It("should have Load, Save, and WithLock methods", func() {
			var s Storage = storage
			Expect(s).NotTo(BeNil())
		})
	})

	Context("FileStorage Load operations", func() {
		It("should return empty TODOList when file does not exist", func() {
			list, err := storage.Load()
			Expect(err).NotTo(HaveOccurred())
			Expect(list).NotTo(BeNil())
			Expect(list.Items).To(BeEmpty())
		})

		It("should load TODOList from existing file with valid JSON", func() {
			// Create test data
			testList := &TODOList{
				Items: []TODOItem{
					{ID: "todo-1", Title: "Test 1", Status: "pending"},
					{ID: "todo-2", Title: "Test 2", Status: "done"},
				},
			}

			// Save first
			err := storage.Save(testList)
			Expect(err).NotTo(HaveOccurred())

			// Load and verify
			loaded, err := storage.Load()
			Expect(err).NotTo(HaveOccurred())
			Expect(loaded.Items).To(HaveLen(2))
			Expect(loaded.Items[0].ID).To(Equal("todo-1"))
			Expect(loaded.Items[1].ID).To(Equal("todo-2"))
		})

		It("should return error when file contains invalid JSON", func() {
			// Write invalid JSON
			filePath := storage.filePath
			err := os.WriteFile(filePath, []byte("invalid json {"), 0644)
			Expect(err).NotTo(HaveOccurred())

			_, err = storage.Load()
			Expect(err).To(HaveOccurred())
		})

		It("should return empty TODOList when file is empty", func() {
			// Create empty file
			filePath := storage.filePath
			err := os.MkdirAll(filepath.Dir(filePath), 0755)
			Expect(err).NotTo(HaveOccurred())
			err = os.WriteFile(filePath, []byte(""), 0644)
			Expect(err).NotTo(HaveOccurred())

			list, err := storage.Load()
			Expect(err).NotTo(HaveOccurred())
			Expect(list.Items).To(BeEmpty())
		})

		It("should handle DependsOn field correctly", func() {
			testList := &TODOList{
				Items: []TODOItem{
					{
						ID:        "todo-1",
						Title:     "Test",
						Status:    "pending",
						DependsOn: []string{"todo-2", "todo-3"},
					},
				},
			}

			err := storage.Save(testList)
			Expect(err).NotTo(HaveOccurred())

			loaded, err := storage.Load()
			Expect(err).NotTo(HaveOccurred())
			Expect(loaded.Items[0].DependsOn).To(Equal([]string{"todo-2", "todo-3"}))
		})
	})

	Context("FileStorage Save operations", func() {
		It("should create file if it doesn't exist", func() {
			testList := &TODOList{
				Items: []TODOItem{{ID: "todo-1", Title: "Test", Status: "pending"}},
			}

			err := storage.Save(testList)
			Expect(err).NotTo(HaveOccurred())

			_, err = os.Stat(storage.filePath)
			Expect(err).NotTo(HaveOccurred())
		})

		It("should overwrite existing file", func() {
			// Save first list
			list1 := &TODOList{
				Items: []TODOItem{{ID: "todo-1", Title: "First", Status: "pending"}},
			}
			err := storage.Save(list1)
			Expect(err).NotTo(HaveOccurred())

			// Save second list
			list2 := &TODOList{
				Items: []TODOItem{{ID: "todo-2", Title: "Second", Status: "done"}},
			}
			err = storage.Save(list2)
			Expect(err).NotTo(HaveOccurred())

			// Verify only second list exists
			loaded, err := storage.Load()
			Expect(err).NotTo(HaveOccurred())
			Expect(loaded.Items).To(HaveLen(1))
			Expect(loaded.Items[0].ID).To(Equal("todo-2"))
		})

		It("should create directory if needed", func() {
			nestedStorage := NewFileStorage(filepath.Join(tempDir, "nested", "dir", "todos.json"))
			testList := &TODOList{
				Items: []TODOItem{{ID: "todo-1", Title: "Test", Status: "pending"}},
			}

			err := nestedStorage.Save(testList)
			Expect(err).NotTo(HaveOccurred())

			_, err = os.Stat(nestedStorage.filePath)
			Expect(err).NotTo(HaveOccurred())
		})

		It("should use atomic write (temp file + rename)", func() {
			testList := &TODOList{
				Items: []TODOItem{{ID: "todo-1", Title: "Test", Status: "pending"}},
			}

			err := storage.Save(testList)
			Expect(err).NotTo(HaveOccurred())

			// Temp file should not exist after successful save
			tempFile := storage.filePath + ".tmp"
			_, err = os.Stat(tempFile)
			Expect(os.IsNotExist(err)).To(BeTrue())
		})

		It("should preserve DependsOn field", func() {
			testList := &TODOList{
				Items: []TODOItem{
					{
						ID:        "todo-1",
						Title:     "Test",
						Status:    "pending",
						DependsOn: []string{"todo-2"},
					},
				},
			}

			err := storage.Save(testList)
			Expect(err).NotTo(HaveOccurred())

			loaded, err := storage.Load()
			Expect(err).NotTo(HaveOccurred())
			Expect(loaded.Items[0].DependsOn).To(Equal([]string{"todo-2"}))
		})
	})

	Context("FileStorage locking", func() {
		It("should acquire and release lock", func() {
			called := false
			err := storage.WithLock(func() error {
				called = true
				return nil
			})
			Expect(err).NotTo(HaveOccurred())
			Expect(called).To(BeTrue())
		})

		It("should execute function within lock", func() {
			testList := &TODOList{
				Items: []TODOItem{{ID: "todo-1", Title: "Test", Status: "pending"}},
			}

			err := storage.WithLock(func() error {
				return storage.Save(testList)
			})
			Expect(err).NotTo(HaveOccurred())

			loaded, err := storage.Load()
			Expect(err).NotTo(HaveOccurred())
			Expect(loaded.Items).To(HaveLen(1))
		})

		It("should return error from function", func() {
			testErr := os.ErrPermission
			err := storage.WithLock(func() error {
				return testErr
			})
			Expect(err).To(Equal(testErr))
		})
	})

	Context("Test isolation", func() {
		It("should not interfere with other tests", func() {
			// Each test uses its own temp directory
			Expect(tempDir).NotTo(BeEmpty())
			Expect(storage.filePath).To(ContainSubstring(tempDir))
		})
	})
})

# CUA MCP Server Implementation Plan

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** Ship a `cua` MCP server in this repository that exposes desktop and browser control tools backed by a containerised XFCE desktop, viewable live over noVNC.

**Architecture:** Our Go binary is the stdio entrypoint of a Docker image built on `trycua/cua-xfce`. It does not implement any tools. It starts nib's `computer` and `browser` MCP servers on in-memory transports, connects a client to each, and re-exposes their merged tool list on a single stdio server. `supervisord` runs XFCE, TigerVNC, and noVNC in the background.

**Tech Stack:** Go 1.25, `github.com/modelcontextprotocol/go-sdk` v1.4.0, `github.com/mudler/nib` (pseudo-version), Ginkgo v2 + Gomega, Docker.

**Spec:** `docs/superpowers/specs/2026-07-20-cua-mcp-design.md`

## Global Constraints

- Go module is the shared `github.com/mudler/mcps`; all code lives in package `main` under `cua/`.
- The module's `go` directive is 1.26 (raised in Task 1 because nib requires it). Builder images must be `golang:1.26` or newer.
- `go build ./...` does not succeed repo-wide until Task 4 adds `cua/main.go`; `cua` has no `main` function before then. This is expected, not a regression.
- nib is pinned to the exact pseudo-version `v0.4.2-0.20260716225335-65925648b37e`. Do not upgrade it as a side effect of any task.
- `github.com/modelcontextprotocol/go-sdk` stays at v1.4.0. nib pins v1.0.0; MVS resolving up to v1.4.0 is verified to compile.
- Configuration is environment variables only. No CLI flags — this matches every other server in this repository.
- The binary must build with `CGO_ENABLED=0`.
- Base image is `trycua/cua-xfce:latest`. `cua-driver` is pinned to `0.9.1`.
- Default `go test ./...` must stay hermetic and fast. Container-dependent tests go behind the `integration` build tag.
- The aggregator must forward tool results verbatim, including `mcp.ImageContent`. Screenshots are the primary output of both toolsets.

---

